    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof deleteHistory>>, TError,DeleteHistoryMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof deleteHistory>>, TError,DeleteHistoryMutationVariables, TContext> => {

const mutationKey = getDeleteHistoryMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof deleteHistory>>, DeleteHistoryMutationVariables> = (props) => {
          const {id} = props ?? {};

          return  deleteHistory(id,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type DeleteHistoryMutationResult = NonNullable<Awaited<ReturnType<typeof deleteHistory>>>

    export type DeleteHistoryMutationError = ErrorType<ErrorResponse>
    export type DeleteHistoryMutationVariables = {id: string}

    export const useDeleteHistory = <TError = ErrorType<ErrorResponse>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof deleteHistory>>, TError,DeleteHistoryMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof deleteHistory>>,
        TError,
        DeleteHistoryMutationVariables,
        TContext
      > => {
      return useMutation(getDeleteHistoryMutationOptions(options), queryClient);
    }

export const getRemediateUrl = () => {




  return `/api/remediate`
}

export const remediate = async (issueInput: IssueInput, options?: Parameters<typeof customFetch>[1]): Promise<Fix> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<Fix>(getRemediateUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(issueInput)
  }
);}





